mapper.select:
        SELECT 
			count(*) 
		FROM 
			REP_REVEAL
		WHERE
			REPORT_NAME = #{reportName,jdbcType=VARCHAR}
		AND PRODID = #{prodId,jdbcType=VARCHAR}
		AND IF(!ISNULL(DATE_FORMAT(START_DATE,'%Y-%m-%d')) , DATE_FORMAT(START_DATE,'%Y-%m-%d') , '0' ) = #{reportDateBegin}
		AND IF(!ISNULL(DATE_FORMAT(END_DATE,'%Y-%m-%d')) , DATE_FORMAT(END_DATE,'%Y-%m-%d') , '0' ) = #{reportDateEnd}
		AND STATUS='E'

mapper.update:
    	UPDATE
   			REP_REVEAL
		SET STATUS = 'D'
			,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
			,UPDATE_TIME = NOW()
		WHERE
			REPORT_NAME = #{reportName,jdbcType=VARCHAR}
		AND PRODID = #{prodId,jdbcType=VARCHAR}
		AND IF(!ISNULL(DATE_FORMAT(START_DATE,'%Y-%m-%d')) , DATE_FORMAT(START_DATE,'%Y-%m-%d'), '0' ) = #{reportDateBegin}
		AND IF(!ISNULL(DATE_FORMAT(END_DATE,'%Y-%m-%d')) ,DATE_FORMAT(END_DATE,'%Y-%m-%d') , '0' ) = #{reportDateEnd}
		AND STATUS='E'
